import { NavLink, Outlet } from 'react-router-dom'
import { clsx } from 'clsx'
import { useAuth } from '@/app/providers/AuthProvider'

const ADMIN_TABS = [
  { path: '/admin/tenant', label: 'Tenant' },
  { path: '/admin/branding', label: 'Branding' },
  { path: '/admin/localization', label: 'Localization' },
  { path: '/admin/apps', label: 'Apps' },
  { path: '/admin/templates', label: 'Templates' },
  { path: '/admin/members', label: 'Members' },
  { path: '/admin/credits', label: 'Credits' },
  { path: '/admin/notifications', label: 'Notifications' },
  { path: '/admin/email-templates', label: 'Email templates' },
  { path: '/admin/legal', label: 'Legal' },
  { path: '/admin/analytics', label: 'Analytics' },
  { path: '/admin/audit', label: 'Audit' },
]

const SUPER_ADMIN_TABS = [
  { path: '/admin/tenants', label: 'All tenants' },
]

export function AdminLayout() {
  const { isSuperAdmin } = useAuth()
  const navClass = ({ isActive }: { isActive: boolean }) =>
    clsx('px-3 py-2 text-sm transition-colors mx-1 my-0.5 rounded-lg',
      isActive ? 'bg-accent/10 text-accent font-medium' : 'text-muted-foreground hover:text-foreground hover:bg-muted')

  return (
    <div className="flex h-full overflow-hidden">
      <aside className="w-48 flex-shrink-0 border-r border-border bg-surface flex flex-col overflow-y-auto">
        <div className="px-3 py-4 border-b border-border">
          <span className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">Admin</span>
        </div>
        {ADMIN_TABS.map((tab) => (
          <NavLink key={tab.path} to={tab.path} className={navClass}>{tab.label}</NavLink>
        ))}
        {isSuperAdmin && (
          <>
            <div className="px-3 pt-4 pb-1 mt-2 border-t border-border">
              <span className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">Platform</span>
            </div>
            {SUPER_ADMIN_TABS.map((tab) => (
              <NavLink key={tab.path} to={tab.path} className={navClass}>{tab.label}</NavLink>
            ))}
          </>
        )}
      </aside>
      <div className="flex-1 flex flex-col overflow-hidden">
        <div className="flex-1 overflow-hidden"><Outlet /></div>
      </div>
    </div>
  )
}
